logger = logging.getLogger("VideoStreamingService")



@dataclass(frozen=True)
class DeviceProfile:
    device_id: str
    user_id: str
    device_type: str  
    capabilities: List[str]
    is_active: bool = True

@dataclass
class VideoAsset:
    video_id: str
