            'session_id': session_id,
            'url': url,
            'event_type': event_type,
            'element_id': element_id,
            'timestamp': timestamp,
            'metadata': metadata or {}
        }

        try:
            self.table.put_item(Item=item)
            return {'status': 'success', 'event_id': event_id}
